import { supabase } from './client'
import type { ObjectiveEvaluation } from '@/entities/objective/types'

export const evaluationsService = {
  async listForObjective(objectiveId: string): Promise<ObjectiveEvaluation[]> {
    const { data, error } = await supabase
      .from('evaluations')
      .select('*')
      .eq('objective_id', objectiveId)
      .order('created_at', { ascending: false })
    if (error) throw error
    return (data ?? []) as ObjectiveEvaluation[]
  },

  async submit(payload: {
    objectiveId: string
    evaluatorId: string
    evaluatorName: string
    rating: number
    feedback?: string
  }): Promise<void> {
    const { error } = await supabase.from('evaluations').insert({
      objective_id: payload.objectiveId,
      evaluator_id: payload.evaluatorId,
      evaluator_name: payload.evaluatorName,
      rating: payload.rating,
      feedback: payload.feedback,
    })
    if (error) throw error
  },
}
